import type { ReactElement } from 'react';
import React, { useState } from 'react';
import type { CCombineSearchItem } from '@cloud-materials/common';
import { CSearch, Space } from '@cloud-materials/common';

const { CCombineSearch } = CSearch;

const educationOptions = [
  {
    label: '专科',
    value: 'junior',
  },
  {
    label: '本科',
    value: 'undergraduate',
  },
  {
    label: '研究生',
    value: 'graduate',
  },
];

const combineList = [
  { label: '名称', fieldName: 'name', type: 'input' },
  {
    label: '状态',
    fieldName: 'status',
    type: 'select',
    mode: 'multiple',
    options: [
      {
        label: '运行中',
        value: 'running',
      },
      {
        label: '已停止',
        value: 'stop',
      },
      {
        label: '安装中',
        value: 'installing',
      },
    ],
  },
  { label: '年龄', fieldName: 'age', type: 'input', mode: 'number', placeholder: '请输入年龄' },
  {
    label: '学历',
    fieldName: 'degree',
    type: 'select',
    options: educationOptions,
  },
];

export default (): ReactElement => {
  const [value, setValue] = useState<Record<string, any>>({
    name: '单向绑定',
    status: ['running', 'stop'],
  });

  return (
    <Space direction="vertical">
      <Space>
        <CSearch.CSimpleSearch
          content={{ component: 'Input' }}
          defaultValue={value.name}
          onChange={val => setValue(v => ({ ...v, name: val }))}
        />
        <CSearch.CSimpleSearch
          style={{ width: 400 }}
          label="双向绑定"
          content={{ component: 'Select', componentProps: { options: combineList[1].options, mode: 'multiple' } }}
          value={value.status}
          onChange={val => setValue(v => ({ ...v, status: val }))}
          debounceOptions={null}
        />
      </Space>
      <h3>受控搜索组件</h3>
      <CCombineSearch
        style={{ width: 800 }}
        list={combineList as CCombineSearchItem[]}
        value={value}
        onChange={params => {
          setValue(params);
          console.log(params);
        }}
      />
    </Space>
  );
};

