  {
    label: '自定义',
    fieldName: 'custom',
    type: 'custom',
    renderContent: ({ value, onChange }) => (
      <CCheckbox.Group direction="vertical" value={value} onChange={onChange} options={customOptions} />
    ),
    renderTrigger: ({ value }) => (
      <CTags>
        {value?.map((v: any) => {
          const temp = customOptions.find(o => o.value === v);
          return <CTag key={temp?.value}>{temp?.label}</CTag>;
