        value: 'Linux-4',
      },
    ],
    allowCreate: true,
    placeholder: '我是单选',
  };
  const customSelect2: CCombineSearchItem = {
    ...customSelect1,
    onSearch({ searchWord, item, filterOptions }) {
      console.log('asd', searchWord);
      if (filterOptions.length === 0) {
        setLoading2('inline');
        setTimeout(() => {
          setData2(pre =>
            uniqBy(
              [
                ...(pre?.filter(el => el.fieldName !== item.fieldName) ?? []),
                {
                  ...item,
                  options: [
                    ...item.options,
                    ...Array.from({ length: 22 }).map((_, index) => {
                      return { label: `${searchWord}-${index}`, value: `${searchWord}-${index}` };
                    }),
                  ],
                },
              ],
              'fieldName',
            ),
          );
          setLoading2('none');
        }, 1000);
      }
    },
  };

  const [data1, setData1] = useState<CCombineSearchItem[] | undefined>(undefined);
  const fetchData = async () => {
    setLoading1('block');
    await new Promise(resolve => {
      setTimeout(resolve, 100);
    });
    setData1([...combineList, customSelect1]);
    setLoading1('none');
  };
  useEffect(() => {
    fetchData();
  }, []);

  const [data2, setData2] = useState<CCombineSearchItem[] | undefined>([...combineList, customSelect2]);
  console.log('asd', data2);
  return (
    <Space direction="vertical">
      <Alert content="输入过程中可点击标签切换字段" />
      <CCombineSearch
        cacheKey="combine"
        fuzzy={true}
        fuzzyConfig={{
          letterCase: 'ignore',
          displayNum: 10,
          enableChangeSearchItem: true,
        }}
        loading={loading1}
        defaultField={{ fieldName: gloablKey }}
        style={{ width: 800 }}
        list={data1}
        onChange={params => {
          console.log(params);
        }}
        // enableEdit={false}
        placeholder="该选字段了"
        extraLeft={
          <Button type="primary" onClick={fetchData}>
            创建实例
          </Button>
        }
        extraRight={
          <Space>
            <Button icon={<IconSearch />} />
            <Button icon={<IconRefresh />} type="primary" />
          </Space>
        }
      />
      <Alert content="远程搜索" />
      <CCombineSearch
        fuzzy={true}
        fuzzyConfig={{
          letterCase: 'ignore',
          displayNum: 10,
          enableChangeSearchItem: true,
          onSearch({ filterList, list, searchWord }) {
            const noOptionsList = filterList.filter(item => item.options.length === 0).map(el => el.fieldName);
            if (!noOptionsList.length) {
              return;
            }
            setLoading2('inline');
            setTimeout(() => {
              setData2(
                list.map(el => {
                  if (el.type === 'select' && noOptionsList.includes(el.fieldName)) {
                    return {
                      ...el,
                      options: [
                        ...el.options,
                        ...Array.from({ length: 22 }).map((_, index) => {
                          return { label: `${searchWord}-${index}-label`, value: `${searchWord}-${index}-value` };
                        }),
                      ],
                    };
                  }
                  return el;
                }),
              );
              setLoading2('none');
            }, 1000);
          },
        }}
        defaultField={{ fieldName: 'instanceId', type: 'auto' }}
        style={{ width: 800 }}
        triggerStyle={{ width: 'auto' }}
        loading={loading2}
        list={data2}
        onChange={params => {
          console.log(params);
        }}
        placeholder="该选字段了"
      />
    </Space>
  );
};

