import { IconSearch } from '@arco-design/iconbox-react-ve-o-design';
import { Input } from '@arco-design/web-react';
import type { AutoCompleteProps } from '@arco-design/web-react';

export default (): ReactElement => {
  const [loading, setLoading] = useState(false);
  const [data, setData] = useState<AutoCompleteProps['data']>([]);
  const fetchData = async (inputValue?: string) => {
    setLoading(true);
    await new Promise(r => {
      setTimeout(r, 1000);
    });
    const options = Array(10)
      .fill(0)
      .map((_, idx) => `${inputValue}-${idx}`);
    setData(options);
    setLoading(false);
  };

  const searchList: CCSearchItem[] = [
    {
      fieldName: 'name1',
      content: {
        component: 'AutoComplete',
        componentProps: {
          data: ['AAA', 'aaa', 'AaA', 'AAa'],
        },
      },
      label: '默认自动补全',
      colspan: 5,
    },
    {
      fieldName: 'name2',
      content: {
        component: 'AutoComplete',
        componentProps: {
          strict: true,
          data: ['AAA', 'aaa', 'AaA', 'AAa'],
        },
      },

      label: '大小写敏感',
      colspan: 5,
    },
    {
      fieldName: 'name3',
      content: {
        component: 'AutoComplete',
        componentProps: {
          triggerElement: <Input prefix={<IconSearch />} />,
          placeholder: '搜索任务',
          data: ['AAA', 'aaa', 'AaA', 'AAa'],
        },
      },
      label: '自定义trigger',
      colspan: 8,
    },
    {
      fieldName: 'name4',
      content: {
        component: 'AutoComplete',
        componentProps: {
          triggerElement: <Input prefix={<IconSearch />} />,
          placeholder: '忽略“,”',
        },
      },
      valueFormatter: (v?: string) => {
        return v?.replaceAll(',', '');
      },
      label: '忽略字符',
      colspan: 8,
    },
    {
      fieldName: 'name5',
      content: {
        component: 'AutoComplete',
        componentProps: {
          onSearch: fetchData,
          placeholder: '搜索任务',
          loading,
          data,
        },
      },
      label: '远端搜索',
      colspan: 8,
    },
  ];
  return (
    <CSearch
      style={{ width: 1000 }}
      list={searchList}
      onChange={params => {
        console.log(params);
      }}
      position="left"
    />
  );
};

