    list: searchList,
    displayCount: 0,
    onChange: params => {
      console.log(params);
    },
  });

  return (
    <CSearch.Provider>
      <Space align="center">
        {value.displayList.map(({ fieldName, content, ...rest }) => (
          <SearchComponent
            {...rest}
            key={fieldName}
            content={content}
            commonProps={
              fieldName
                ? {
                    value: value.params[fieldName],
                    onChange: (val: any) => {
                      control.updateParams({ [fieldName]: val });
                    },
                  }
                : undefined
            }
          />
        ))}
        {value.advanceList.length > 0 && (
          <Popover
            trigger="click"
            position="bl"
            popupVisible={value.advanceVisible}
            onVisibleChange={control.toggleAdvanceVisible}
            content={
              <Space wrap>
                {value.advanceList.map(({ fieldName, content, ...rest }) => (
                  <SearchComponent
                    {...rest}
                    key={fieldName}
                    content={content}
                    commonProps={
                      fieldName
                        ? {
                            value: value.params[fieldName],
                            onChange: (val: any) => {
                              control.updateParams({ [fieldName]: val });
                            },
                          }
                        : undefined
                    }
                  />
                ))}
              </Space>
            }
          >
            <Button>添加搜索项</Button>
          </Popover>
        )}
        <Button onClick={control.resetParams}>重置</Button>
        <Button icon={<IconRefresh />} onClick={() => control.search()} />
      </Space>
      <pre>{JSON.stringify(value.params, null, 2)}</pre>
    </CSearch.Provider>
  );
};

